\section{Preliminary material}
\label{app:prelim}

\subsection{Conventions and coordinates}

We use $\hbar=1$, natural logarithms, and the convention $0\ln0=0$.
The number operator is $\hat n=(\hat x^2+\hat p^2-1)/2$, and the vacuum Wigner function is denoted by
\begin{equation}
 W_0(x,p):=W_{\ketbra00}(x,p)=\frac1\pi e^{-(x^2+p^2)}.
 \label{eq:s-vacuum-wigner}
\end{equation}
All the states considered below have finite support in the Fock basis, so that their Wigner functions are the product of a Gaussian function and a polynomial function; in particular, all the Gaussian moments appearing in our calculations are finite.
Recall that the Wigner transform is linear, satisfies $\int_{\R^2}W_A\dd x\dd p=\Tr A$ for the finite-rank operators considered here, and obeys the overlap identity~\cite{moyal1949}
\begin{equation}
 \Tr(AB)=2\pi\int_{\R^2}W_AW_B\dd x\dd p.
 \label{eq:s-moyal}
\end{equation}

For polar integration, we write
\begin{equation}
 x+ip=\sqrt R\,e^{i\theta},\qquad R=x^2+p^2,\qquad
 \dd x\dd p=\frac12\dd R\dd\theta.
 \label{eq:s-polar-conventions}
\end{equation}
Thus $R$ is the squared radius, and $W_0\dd x\dd p=e^{-R}\dd R\dd\theta/(2\pi)$.

\subsection{Fock basis and Laguerre polynomials}

For integers $0\le m\le n$, the Wigner transform of a Fock basis operator is~\cite{wunsche1998laguerre}
\begin{equation}
 \frac{W_{\ketbra mn}(R,\theta)}{W_0(R)}
 =(-1)^m\sqrt{\frac{m!}{n!}}
 (\sqrt{2R}\,e^{i\theta})^{n-m}L_m^{(n-m)}(2R).
 \label{eq:s-associated-laguerre}
\end{equation}
Here $L_m^{(n-m)}$ is a generalized Laguerre polynomial; the case $m>n$ follows from $W_{\ketbra nm}=W_{\ketbra mn}^*$.
In particular, for the operators $\ketbra{n}{n}$ and $\ketbra{0}{n}+\ketbra{n}{0}$, we obtain
\begin{align}
 W_{\ketbra nn}(R)&=W_0(R)(-1)^nL_n(2R),
 \label{eq:s-diagonal-fock}\\
 W_{\ketbra0n+\ketbra n0}(R,\theta)
 &=W_0(R)\frac{2(2R)^{n/2}}{\sqrt{n!}}\cos(n\theta).
 \label{eq:s-interference}
\end{align}
We use the convention~\cite{olver2010}
\begin{equation}
 L_n(z)=\sum_{k=0}^n(-1)^k\binom nk\frac{z^k}{k!},
 \qquad
 (-1)^nL_n(z)=\frac{z^n-n^2z^{n-1}}{n!}+O(z^{n-2})
 \quad(z\to\infty,\ n\ge2).
 \label{eq:s-laguerre-full}
\end{equation}
The $n$ zeros $r_1,\ldots,r_n$ of $L_n$ are simple and strictly positive~\cite[Sec.~18.2(vi)]{olver2010}, and
\begin{equation}
 (-1)^nL_n(z)=\frac1{n!}\prod_{j=1}^n(z-r_j),
 \qquad \sum_{j=1}^n r_j=n^2.
 \label{eq:s-laguerre-zeros}
\end{equation}
Indeed, the coefficient of $z^{n-1}$ in this product is $-\sum_{j=1}^n r_j/n!$, which must match the coefficient $-n^2/n!$ in Eq.~\eqref{eq:s-laguerre-full}.
These facts will be used in Appendix~\ref{app:explicit-coherence}.

\subsection{Gaussian integrals}

We use the following notation for integration with a normalized Gaussian weight:
\begin{equation}
 \int_{\R^2}f\dd\nu_\alpha
 :=\frac{\alpha}{\pi}\int_{\R^2}f(x,p)e^{-\alpha R}\dd x\dd p,
 \qquad \alpha>0.
 \label{eq:s-nu-alpha}
\end{equation}
Thus $\nu_\alpha$ is a probability measure, with $\dd\nu_1=W_0\dd x\dd p$ for the vacuum.
The weights $\nu_{\alpha}$ with $\alpha\neq 1$ will be needed for the R\'enyi entropies, since $W^{\alpha}_{0}$ is proportional to $e^{-\alpha R}$.
For non-negative integers $j,\ell,k$, the required integrals are
\begin{align}
 \int_0^\infty e^{-\alpha R}R^k\dd R&=\frac{k!}{\alpha^{k+1}},
 \label{eq:s-gaussian-radial}\\
 \int_{\R^2}x^{2j}p^{2\ell}\dd\nu_\alpha
 &=\frac{(2j-1)!!(2\ell-1)!!}{(2\alpha)^{j+\ell}}.
 \label{eq:s-three-renyi-moments}
\end{align}
Here $(2j-1)!!=1\cdot3\cdots(2j-1)$ for $j\ge1$ is the double factorial, with the convention $(-1)!!=1$.
Any moment odd in $x$ or $p$ vanishes.
For $n\ge1$, the angular integrals are
\begin{align}
 \int_0^{2\pi}\cos(n\theta)\dd\theta=0,
 \qquad \int_0^{2\pi}\cos^2(n\theta)\dd\theta=\pi.
\end{align}
Integrating the finite sum in Eq.~\eqref{eq:s-laguerre-full} gives
\begin{equation}
 \alpha\int_0^\infty e^{-\alpha R}(-1)^nL_n(2R)\dd R
 =\left(\frac{2-\alpha}{\alpha}\right)^n.
 \label{eq:s-renyi-laguerre-moment}
\end{equation}
At $\alpha=1$, this reduces to the normalization $\int_0^\infty e^{-R}(-1)^nL_n(2R)\dd R=1$.

\subsection{Entropies relative to the vacuum}

For a normalized non-negative Wigner function, the Wigner entropy and Wigner--R\'enyi entropy of order $\alpha$ are defined as~\cite{renyi1961,vanherstraeten2021}
\begin{equation}
 h(W)=-\int_{\R^2}W\ln W\dd x\dd p,
 \qquad
 h_\alpha(W)=\frac1{1-\alpha}\ln\int_{\R^2}W^\alpha\dd x\dd p
 \quad(\alpha>0,\ \alpha\ne1).
 \label{eq:s-entropy-definitions}
\end{equation}
For the vacuum, these definitions give
\begin{equation}
 h(W_0)=1+\ln\pi,
 \qquad h_\alpha(W_0)=\ln\pi+\frac{\ln\alpha}{\alpha-1}.
 \label{eq:s-vacuum-renyi}
\end{equation}
For normalized $W$, the Wigner--R\'enyi entropy tends to the Wigner entropy as $\alpha\to1$.

It is convenient to express a Wigner function as a relative perturbation of the vacuum,
\begin{equation}
 W=W_0(1+\delta),\qquad 1+\delta\ge0,
 \qquad \int_{\R^2}\delta\dd\nu_1=0.
 \label{eq:s-relative-perturbation}
\end{equation}
Its relative entropy with respect to the vacuum is
\begin{equation}
 D(W\Vert W_0)
 \coloneqq
\int_{\mathbb{R}^2}
W\ln\frac{W}{W_0}\dd x\dd p
 =
 \int_{\R^2}(1+\delta)\ln(1+\delta)\dd\nu_1.
 \label{eq:s-relative-entropy}
\end{equation}
Since $\ln W_0=-\ln\pi-R$ and $\int RW\dd x\dd p=2\langle\hat n\rangle+1$, the entropy difference is
\begin{equation}
 h(W)-h(W_0)=2\langle\hat n\rangle-D(W\Vert W_0),
 \label{eq:s-entropy-identity}
\end{equation}
where $\langle\hat{n}\rangle=\Tr(\rho\,\hat{n})$ is the mean photon number of the state.
Thus the entropy lies below the vacuum value precisely when $D(W\Vert W_0)>2\langle\hat n\rangle$.
For the Wigner--R\'enyi entropies, the corresponding identity is
\begin{equation}
 h_\alpha(W)-h_\alpha(W_0)
 =\frac1{1-\alpha}\ln\int_{\R^2}(1+\delta)^\alpha\dd\nu_\alpha.
 \label{eq:s-renyi-ratio}
\end{equation}

\subsection{Control of entropy expansions}
\label{sec:s-expansion-control}

All the counterexamples constructed in this work are states close to the vacuum, and our strategy to compute their entropy is always the same: we write $W=W_0(1+\delta)$ as in Eq.~\eqref{eq:s-relative-perturbation}, where $\delta$ vanishes as the state approaches the vacuum, and we expand the integrals appearing in Eqs.~\eqref{eq:s-relative-entropy} and~\eqref{eq:s-renyi-ratio} in powers of $\delta$.
Note that $\delta$ is small only in a pointwise sense: for the states considered here, $W/W_0$ is a polynomial in $x$ and $p$, so that $\delta$ tends to zero at each fixed point but grows with $R$, and $\delta$ even reaches the value $-1$ at the zeros of the Wigner function.
The Taylor expansions of $(1+z)\ln(1+z)$ and $(1+z)^\alpha$ around $z=0$ can therefore not be integrated term by term without further justification.
More precisely, we shall need remainder bounds valid on the whole range $z\ge-1$, which we collect here since they are used repeatedly in Appendices~\ref{app:0n}--\ref{app:Renyi}.

The first bound concerns the Shannon relative entropy~\eqref{eq:s-relative-entropy}.
For every $z\ge-1$, we have
\begin{equation}
 0\le\Phi(z):=(1+z)\ln(1+z)-z\le z^2,
 \qquad
 \lim_{z\to0}\frac{\Phi(z)}{z^2}=\frac12.
 \label{eq:s-shannon-global-bound}
\end{equation}
The lower bound follows from convexity and $\Phi(0)=\Phi'(0)=0$, the upper bound from $\ln(1+z)\le z$ (the case $z=-1$ follows by continuity), and the limit from the Taylor expansion at zero.
Its R\'enyi analogue, which concerns the integrand of Eq.~\eqref{eq:s-renyi-ratio}, reads, for fixed $0<\alpha<2$ and $z\ge-1$,
\begin{equation}
 |(1+z)^\alpha-1-\alpha z|\le C_\alpha z^2,
 \qquad
 \lim_{z\to0}\frac{(1+z)^\alpha-1-\alpha z}{z^2}
 =\frac{\alpha(\alpha-1)}2,
 \label{eq:s-renyi-linear-bound}
\end{equation}
where $C_\alpha$ is a finite constant depending only on $\alpha$.
Indeed, the quotient extends continuously to $z=0$ and $z=-1$ and tends to zero at infinity because $\alpha<2$, so that it is bounded on $[-1,\infty)$.

In several of the cases treated below, the leading term of this expansion cancels out, and the sign of the entropy difference is only decided at higher order.
We shall then need to carry the expansion further, while keeping its remainder under control on the whole range $z\ge-1$.
For $F(y)=y\ln y$ or $F(y)=y^\alpha$ with fixed $0<\alpha<2$, we shall therefore also use the bound
\begin{equation}
 \left|F(1+z)-\sum_{k=0}^7\frac{F^{(k)}(1)}{k!}z^k\right|
 \le C_F|z|^8,
 \qquad z\ge-1,
 \label{eq:s-global-taylor}
\end{equation}
where $C_F$ is a finite constant depending only on $F$ (and hence possibly on $\alpha$).
To prove it, divide the left-hand side by $|z|^8$: the resulting quotient is bounded near zero by Taylor's theorem, remains finite at $z=-1$ by continuity, and tends to zero at infinity because $F(1+z)=o(z^8)$ while the Taylor polynomial has degree at most seven.
Since it is continuous elsewhere, it is bounded on $[-1,\infty)$, which proves Eq.~\eqref{eq:s-global-taylor}.

\section{States supported on the vacuum and one Fock level}
\label{app:0n}

For $n\ge1$, consider again the family of states of Eq.~\eqref{eq:state} in the main text,
\begin{equation}
 \rho_n(t,s)=(1-t)\ketbra00+t\ketbra nn
 +s(\ketbra0n+\ketbra n0),\qquad 0\le t\le1.
 \label{eq:s-state}
\end{equation}
All asymptotic statements for this family refer to $t\to0^+$ with $n$ fixed; constants in the remainder estimates may depend on $n$.
A phase rotation makes $s$ real and non-negative without changing either Wigner positivity or entropy.
Positive semi-definiteness of $\rho_n(t,s)$ amounts to $s^2\le t(1-t)$.
We first determine the largest coherence allowed by Wigner positivity, then give an explicit alternative that produces the same leading entropy decrease.

\subsection{Wigner positivity and maximal coherence}
\label{sec:s-maximal-coherence}

Equations~\eqref{eq:s-diagonal-fock} and \eqref{eq:s-interference} give
\begin{equation}
 \frac{W_{\rho_n(t,s)}}{W_0}
 =1-t+t(-1)^nL_n(2R)
 +\frac{2s(2R)^{n/2}}{\sqrt{n!}}\cos(n\theta).
 \label{eq:s-family-wigner}
\end{equation}
For each $R>0$, the minimum over the angle is obtained at $\cos(n\theta)=-1$.
Consequently,
\begin{equation}
 W_{\rho_n(t,s)}\ge0
 \quad\Longleftrightarrow\quad
 1-t+t(-1)^nL_n(2R)\ge\frac{2s(2R)^{n/2}}{\sqrt{n!}}
 \quad\text{for all }R\ge0.
 \label{eq:s-radial-positivity}
\end{equation}
As shown in Appendix~\ref{app:explicit-coherence}, this condition is satisfied by a whole interval of values $s\geq 0$ as soon as $t$ is small enough.

At fixed $t$, the states $\rho_n(t,s)$ and $\rho_n(t,-s)$ have the same Wigner entropy, since their Wigner functions are related by a phase-space rotation.
Mixing these two states produces all possible coherence values between $-s$ and $s$ and cannot lower their common Wigner entropy, by concavity of the Shannon entropy.
We therefore seek the largest non-negative coherence compatible with Wigner positivity, which minimizes the Wigner entropy within this family at fixed $t$.

We must also check that this choice satisfies the positive semi-definiteness constraint $s\le\sqrt{t(1-t)}$.
At equality, $\rho_n(t,s)$ is the projector onto $\sqrt{1-t}\ket0+\sqrt t\ket n$.
This pure state is non-Gaussian, so its Wigner function takes negative values by Hudson's theorem~\cite{hudson1974}.
Since the right-hand side of the radial condition increases with $s$, Wigner positivity imposes a strictly smaller upper bound and therefore already enforces the positive semi-definiteness constraint.
Taking the infimum of the bounds in Eq.~\eqref{eq:s-radial-positivity} over $R>0$ gives the maximal admissible coherence:
\begin{equation}
 s_n(t)=
 \inf_{R>0}\frac{\sqrt{n!}[1-t+t(-1)^nL_n(2R)]}{2(2R)^{n/2}}.
 \label{eq:s-sn}
\end{equation}

Following the main text, we write $h_n(t):=h(W_{\rho_n(t,s_n(t))})$ for the Wigner entropy at maximal coherence.

\subsection{An explicit admissible coherence}
\label{app:explicit-coherence}

The expression for $s_n(t)$ in Eq.~\eqref{eq:s-sn} requires a minimization over $R$.
We now seek a simpler explicit expression for an admissible coherence with the same leading behavior as $s_n(t)$ when $t\to0^+$.
This will also provide an explicit lower bound on $s_n(t)$.

We consider $0\le s\le\sqrt{t(1-t)}$ and write $z=2R$.
The Wigner positivity condition~\eqref{eq:s-radial-positivity} becomes
\begin{align}
 1-t+t(-1)^nL_n(z)
 \ge \frac{2s z^{n/2}}{\sqrt{n!}}.
\end{align}
We split the domain at $z=n^2$, since every Laguerre zero satisfies $0<r_j\le\sum_{k=1}^n r_k=n^2$.
On $0\le z\le n^2$, the left-hand side tends uniformly to $1$ as $t\to0^+$, because $L_n(z)$ is bounded.
The right-hand side tends uniformly to $0$ for all allowed $s$, because $z^{n/2}$ is bounded and $s\le\sqrt t$.
Thus the condition holds throughout this interval for all sufficiently small $t>0$.

For $z\ge n^2$, the factorization in Eq.~\eqref{eq:s-laguerre-zeros} gives
\begin{equation}
 (-1)^nL_n(z)
 =\frac{z^n}{n!}\prod_{j=1}^n\left(1-\frac{r_j}{z}\right)
 \ge\frac{z^n-n^2z^{n-1}}{n!}.
 \label{eq:s-laguerre-tail-bound}
\end{equation}
Here $0\le r_j/z\le1$, so the inequality follows from $\prod_j(1-a_j)\ge1-\sum_j a_j$ for $a_j\in[0,1]$.

We divide the Wigner positivity condition by $1-t$ and introduce $u$ so that the leading term $tz^n/[(1-t)n!]$ becomes $u^n$:
\begin{align}
 u=z\left(\frac{t}{(1-t)n!}\right)^{1/n},
 \qquad
 \gamma=n^2\left(\frac{t}{(1-t)n!}\right)^{1/n}.
\end{align}
Using Eq.~\eqref{eq:s-laguerre-tail-bound}, we obtain
\begin{align}
 \frac{1-t+t(-1)^nL_n(z)}{1-t}
 &\ge 1+u^n-\gamma u^{n-1},\\
 \frac{2s z^{n/2}}{(1-t)\sqrt{n!}}
 &=\frac{2s}{\sqrt{t(1-t)}}\,u^{n/2}.
\end{align}
We therefore seek a lower bound on $1+u^n-\gamma u^{n-1}$ proportional to $u^{n/2}$.

For sufficiently small $t>0$, we have $0<\gamma<1$.
Using $u^{n-1}\le1$ when $0\le u\le1$ and $u^{n-1}\le u^n$ when $u\ge1$ gives
\begin{align}
 1+u^n-\gamma u^{n-1}
 \ge
 \begin{cases}
  (1-\gamma)+u^n, & 0\le u\le1,\\
  1+(1-\gamma)u^n, & u\ge1.
 \end{cases}
\end{align}
By the arithmetic--geometric mean inequality, both lower bounds are at least $2\sqrt{1-\gamma}\,u^{n/2}$.
Comparison with the normalized right-hand side therefore shows that Wigner positivity is guaranteed whenever
\begin{align}
 0\le s\le\sqrt{t(1-t)(1-\gamma)}.
\end{align}

This already provides a lower bound on $s_n(t)$.
We simplify it by replacing $\gamma$ with an upper bound that does not involve $n!$.
Indeed, $\ln(n!)\ge\int_1^n\ln x\,\dd x>n\ln n-n$ implies $(n!)^{1/n}>n/e$, and hence
\[
 \frac{\gamma}{t^{1/n}}
 \longrightarrow\frac{n^2}{(n!)^{1/n}}<en.
\]
Thus $\gamma\le en\,t^{1/n}<1$ for all sufficiently small $t>0$.
Replacing $\gamma$ by this upper bound gives a smaller admissible coherence, and therefore
\begin{equation}
 \sqrt{(1-t)(1-en\,t^{1/n})}
 \le\frac{s_n(t)}{\sqrt t}
 \le\sqrt{1-t}.
 \label{eq:s-coherence-limit}
\end{equation}
Both bounds tend to one when $t\to0^+$, proving $s_n(t)^2=t+o(t)$, and implying $s_n(t)=O(\sqrt{t})$.
For $n=1,2$, the same asymptotic behavior follows from the bounds in Appendix~\ref{app:s-low-levels}.

For $n\ge3$, the construction yields the following explicit admissible coherence, with the same leading behavior as $s_n(t)$:
\begin{equation}
 \widetilde s_n(t)=\sqrt{t(1-t)\bigl(1-en\,t^{1/n}\bigr)}.
 \label{eq:s-explicit-coherence}
\end{equation}

\subsection{Asymptotic Wigner entropy}
\label{sec:s-binary-entropy}

We now take either the maximal coherence $s=s_n(t)$, for any fixed $n\ge1$, or the explicit coherence $s=\widetilde s_n(t)$, for fixed $n\ge3$.
Both choices give Wigner-positive states for sufficiently small $t$, with $s^2=t+o(t)$.
The coefficient of $\ket n$ contributes $2nt$ to Eq.~\eqref{eq:s-entropy-identity}, while the entropy-lowering contribution will come from the square of the coherence.

For use here and in the Wigner--R\'enyi entropy calculations in Appendix \ref{app:Renyi}, write
\begin{equation}
 A_n(R)=(-1)^nL_n(2R)-1,
 \qquad
 B_n(R,\theta)=\frac{2(2R)^{n/2}}{\sqrt{n!}}\cos(n\theta),
 \label{eq:s-binary-components}
\end{equation}
so that the relative perturbation is
\begin{equation}
 \delta_{n,t}=\frac{W_{\rho_n(t,s)}}{W_0}-1=tA_n+sB_n.
 \label{eq:s-relative-deviation}
\end{equation}
Equations~\eqref{eq:s-gaussian-radial} and \eqref{eq:s-renyi-laguerre-moment}, together with integration over $\theta$, give
\begin{equation}
 \int A_n\dd\nu_1=\int B_n\dd\nu_1=0,
 \qquad
 \int B_n^2\dd\nu_\alpha
 =\frac{4\cdot2^n}{n!}\cdot\frac{\alpha}{2\pi}
 \int_0^\infty e^{-\alpha R}R^n\dd R\int_0^{2\pi}\cos^2(n\theta)\dd\theta
 =\frac{2^{n+1}}{\alpha^n}.
 \label{eq:s-binary-moments}
\end{equation}
In particular, $\int B_n^2\dd\nu_1=2^{n+1}$, which is the value needed here. We use the case of general $\alpha$ in Appendix~\ref{app:Renyi}.

We now expand $D(W_{\rho_n(t,s)}\Vert W_0)$ to first order in $t$.
Since $\int\delta_{n,t}\dd\nu_1=0$, Eq.~\eqref{eq:s-relative-entropy} gives $D(W_{\rho_n(t,s)}\Vert W_0)=\int\Phi(\delta_{n,t})\dd\nu_1$ with $\Phi$ as in Eq.~\eqref{eq:s-shannon-global-bound}.
At each fixed point, $\delta_{n,t}/\sqrt t\to B_n$ because $s/\sqrt t\to1$, hence $\Phi(\delta_{n,t})/t\to B_n^2/2$ by the limit in Eq.~\eqref{eq:s-shannon-global-bound}.
Moreover, $s^2\le t$ and $t\le1$ imply the bound
\begin{equation}
 0\le\frac{\Phi(\delta_{n,t})}{t}
 \le\frac{\delta_{n,t}^2}{t}\le2A_n^2+2B_n^2.
 \label{eq:s-binary-dominating-bound}
\end{equation}
The right-hand side is integrable against $\nu_1$ because it grows only polynomially with $R$.
Dominated convergence therefore gives
\begin{equation}
 D(W_{\rho_n(t,s)}\Vert W_0)
 =\int\Phi(\delta_{n,t})\dd\nu_1
 =2^nt+o(t).
 \label{eq:s-nonlinear-result}
\end{equation}
Note that the argument does not require $1+\delta_{n,t}$ to stay away from zero, since the bound~\eqref{eq:s-shannon-global-bound} holds down to $z=-1$; the points where the Wigner function of $\rho_n(t,s_n(t))$ vanishes therefore cause no difficulty.
Since $\langle\hat n\rangle=nt$, Eq.~\eqref{eq:s-entropy-identity} now yields
\begin{equation}
 h(W_{\rho_n(t,s)})=1+\ln\pi+(2n-2^n)t+o(t).
 \label{eq:s-main-expansion}
\end{equation}
In particular, this is the expansion of $h_n(t)$, and it also holds for the explicit admissible coherence.
For every fixed $n\ge3$, the coefficient is negative, so both choices give counterexamples for all sufficiently small positive $t$.
They approach the vacuum in trace distance: $\tfrac12\|\rho_n(t,s)-\ketbra00\|_1=\sqrt{t^2+s^2}\to0$.

Finally, let us justify the identification of the Gaussification of $\rho_n(t,s)$ used in the main text.
For $n\ge3$, the coherence between $\ket0$ and $\ket n$ contributes to neither the first nor the second moments, so the first moments vanish and the covariance matrix is $(nt+1/2)I$.
The Gaussian state with these moments is therefore the thermal state with mean photon number $nt$.

\subsection{The cases \texorpdfstring{$n=1$ and $n=2$}{n=1 and n=2}}
\label{app:s-low-levels}

Recall from the main text that a beam-splitter state is the reduced output of a balanced beam splitter fed with a separable two-mode input, and that all such states satisfy the Wigner entropy conjecture~\cite{interference2025}.
We show here that every Wigner-positive state in $\operatorname{span}\{\ket0,\ket1\}$ or $\operatorname{span}\{\ket0,\ket2\}$ is a beam-splitter state, which proves the conjecture in both sectors.
Throughout this subsection, the beam splitter acts as $a^\dagger\mapsto(a^\dagger+b^\dagger)/\sqrt2$, $b^\dagger\mapsto(a^\dagger-b^\dagger)/\sqrt2$, $\ket{nm}$ denotes $n$ photons in the first mode and $m$ in the second, and the second mode is the one being traced out.

For $n=1$ and $t>0$, completing the square gives
\begin{equation}
 \frac{W_{\rho_1(t,s)}}{W_0}
 =2t\left[\left(x+\frac{s}{\sqrt2t}\right)^2+p^2\right]
 +1-2t-\frac{s^2}{t}.
 \label{eq:s-n1-positivity}
\end{equation}
Wigner positivity is therefore equivalent to $t\le1/2$ and $s^2\le t(1-2t)$, with maximal coherence $s_1(t)=\sqrt{t(1-2t)}$, i.e., Eq.~\eqref{eq:s-sn} for $n=1$.
These are exactly the conditions for $\rho_1(2t,\sqrt2s)$ to be a valid input state.
A direct derivation shows that mixing that state with the vacuum at a balanced beam splitter gives $\rho_1(t,s)$.

For $n=2$, minimizing the ratio $W_{\rho_2(t,s)}/W_0$ over $\theta$ at fixed $R$ gives
\begin{align}
 \min_\theta\frac{W_{\rho_2(t,s)}(R,\theta)}{W_0(R)}
 =1-(4t+2\sqrt2s)R+2tR^2.
\end{align}
Minimizing this quadratic over $R\ge0$ yields
\begin{equation}
 0\le t\le\frac12,
 \qquad 0\le s\le s_2(t)=\sqrt t-\sqrt2t.
 \label{eq:s-s2}
\end{equation}
Thus $s_2(t)$ is the maximal coherence~\eqref{eq:s-sn} for $n=2$.
Now set $t'=\sqrt{2t}$ and consider the product input
\begin{align}
 \bigl(\sqrt{1-t'}\ket0+\sqrt{t'}\ket1\bigr)
 \otimes\bigl(\sqrt{1-t'}\ket0-\sqrt{t'}\ket1\bigr).
\end{align}
The beam splitter maps it to
\begin{equation}
 (1-t')\ket{00}+\sqrt{2t'(1-t')}\ket{01}
 -\frac{t'}{\sqrt2}\ket{20}+\frac{t'}{\sqrt2}\ket{02}.
 \label{eq:s-n2-beamsplitter-output}
\end{equation}
Tracing out the second mode gives $\rho_2(t,-s_2(t))$, and a phase rotation gives the opposite coherence.
For $0<t<1/2$ and $0\le s\le s_2(t)$, all intermediate coherences are obtained from
\begin{align}
 \rho_2(t,s)=\lambda\rho_2(t,s_2(t))+(1-\lambda)\rho_2(t,-s_2(t)),
 \qquad \lambda=\frac12\left(1+\frac{s}{s_2(t)}\right).
\end{align}
These mixtures remain beam-splitter states because separable inputs form a convex set.
The endpoints $t=0$ and $t=1/2$ follow directly from the construction with $t'=0$ and $t'=1$.
This proves the entropy bound in both sectors.

For completeness, we also determine the first nonzero term of $h_2(t)-h(W_0)$, where $h_2(t)=h(W_{\rho_2(t,s_2(t))})$, which shows that the $n=2$ curve in Fig.~\ref{fig:results} approaches the vacuum value from above:
\begin{equation}
 h_2(t)-h(W_0)=8\sqrt2\,t^{3/2}+O(t^2).
 \label{eq:s-n2-entropy-expansion}
\end{equation}
Indeed, write $\delta_{2,t}=tA_2+s_2(t)B_2$ as in Eq.~\eqref{eq:s-relative-deviation}.
Angular integration gives $\int A_2B_2\dd\nu_1=\int B_2^3\dd\nu_1=0$, and hence
\begin{align}
 \int\delta_{2,t}^2\dd\nu_1=8s_2(t)^2+O(t^2),
 \qquad \int\delta_{2,t}^3\dd\nu_1=O(t^2).
\end{align}
For $4\le k\le8$, the bound in Eq.~\eqref{eq:s-binary-dominating-bound} gives $\int|\delta_{2,t}|^k\dd\nu_1=O(t^{k/2})$.
The Taylor expansion with the bound~\eqref{eq:s-global-taylor} therefore yields $D(W_{\rho_2(t,s_2(t))}\Vert W_0)=4s_2(t)^2+O(t^2)$.
Using $h_2(t)-h(W_0)=4t-D(W_{\rho_2(t,s_2(t))}\Vert W_0)$ and substituting Eq.~\eqref{eq:s-s2} proves Eq.~\eqref{eq:s-n2-entropy-expansion}.

Finally, no Wigner-positive state is supported only on $\operatorname{span}\{\ket1,\ket2\}$: indeed, Eq.~\eqref{eq:s-moyal} gives $\langle0|\rho|0\rangle=2\pi\int W_\rho W_0\dd x\dd p>0$ for every Wigner-positive state, since $W_0$ is strictly positive.
Together with the two cases above, this shows that all three lowest Fock levels are needed for a counterexample in $\operatorname{span}\{\ket0,\ket1,\ket2\}$, which is the object of the next appendix.

\section{Counterexamples in the \texorpdfstring{$0$--$1$--$2$}{0--1--2} sector}
\label{app:012}

We now construct counterexamples supported on $\operatorname{span}\{\ket0,\ket1,\ket2\}$.
Consider again the normalized vector of Eq.~\eqref{eq:three-level-state} in the main text,
\begin{equation}
 \ket{\phi_\epsilon}
 =\frac{\ket0+\sqrt{2\epsilon}\ket1+\epsilon\ket2/\sqrt2}
 {\sqrt{N_\epsilon}},
 \qquad N_\epsilon=1+2\epsilon+\frac{\epsilon^2}{2}.
 \label{eq:s-three-pure-state}
\end{equation}
This choice of coefficients leads to a simple expression for the Wigner function used in the proof below.
We mix this state with $\ket2$:
\begin{equation}
 \sigma_\epsilon=(1-\epsilon^4)\ketbra{\phi_\epsilon}{\phi_\epsilon}
 +\epsilon^4\ketbra22,
 \qquad 0<\epsilon<1.
 \label{eq:s-three-mixture}
\end{equation}
The weight $\epsilon^4$ will suffice to restore Wigner positivity while leaving the polynomial ratio to $W_0$ unchanged through order $\epsilon^3$.
All asymptotic statements for this family refer to $\epsilon\to0^+$.
Note that $\sigma_\epsilon$ is a mixed state of rank two since $\ket{2}$ and $\ket{\phi_\epsilon}$ are linearly independent.
We first prove that $\sigma_\epsilon$ is Wigner-positive for sufficiently small $\epsilon>0$, then compute its entropy up to order $\epsilon^3$.

\subsection{Wigner positivity}

Expanding $\ketbra{\phi_\epsilon}{\phi_\epsilon}$ in the Fock basis and applying Eq.~\eqref{eq:s-associated-laguerre} gives
\begin{equation}
 \frac{W_{\ketbra{\phi_\epsilon}{\phi_\epsilon}}}{W_0}
 =\frac{(q_\epsilon-\epsilon)^2-\epsilon^2/2}{N_\epsilon},
 \qquad
 q_\epsilon=1+2\sqrt\epsilon\,x+\epsilon R
 =\epsilon\bigl[(x+\epsilon^{-1/2})^2+p^2\bigr].
 \label{eq:s-three-pure-wigner}
\end{equation}
Consequently,
\begin{equation}
 \frac{W_{\sigma_\epsilon}}{W_0}
 =\frac{1-\epsilon^4}{N_\epsilon}
 \bigl[(q_\epsilon-\epsilon)^2-\epsilon^2/2\bigr]
 +\epsilon^4 P_2(R),
 \qquad P_2(R)=\frac{W_{\ketbra22}(R)}{W_0(R)}=1-4R+2R^2.
 \label{eq:s-three-wigner-ratio}
\end{equation}

Before giving the proof, let us explain why a weight of order $\epsilon^4$ on $\ket2$ suffices to restore Wigner positivity.
The two terms in Eq.~\eqref{eq:s-three-wigner-ratio} are negative in two disjoint regions of phase space.
The Wigner function of $\ket{\phi_\epsilon}$ is negative precisely where
\begin{align}
 1-\frac1{\sqrt2}
 <(x+\epsilon^{-1/2})^2+p^2
 <1+\frac1{\sqrt2},
\end{align}
that is, on an annulus centered at $(-\epsilon^{-1/2},0)$ with radii independent of $\epsilon$, and it is bounded below by $-\epsilon^2/(2N_\epsilon)$.
On this annulus, $R=\epsilon^{-1}+O(\epsilon^{-1/2})$ uniformly, so that $\epsilon^4P_2(R)\sim2\epsilon^2$, which is enough to compensate for the negative contribution of $\ket{\phi_\epsilon}$ when $\epsilon$ is small.
Conversely, $P_2(R)$ is negative only on a fixed annulus around the origin, where $\epsilon^4P_2(R)\ge-\epsilon^4$ while $(1-\epsilon^4)W_{\ketbra{\phi_\epsilon}{\phi_\epsilon}}/W_0$ tends uniformly to one.

Let us now make this argument rigorous.
We shall prove that
\begin{equation}
 W_{\sigma_\epsilon}(x,p)>0
 \quad\text{for every }(x,p)\in\R^2
 \quad\text{if }0<\epsilon\le\frac1{100}.
 \label{eq:s-three-explicit-range}
\end{equation}
The value $1/100$ is chosen for convenience and is not optimal.
Multiplying Eq.~\eqref{eq:s-three-wigner-ratio} by the positive factor $N_\epsilon/(1-\epsilon^4)$, it suffices to show that
\begin{equation}
 (q_\epsilon-\epsilon)^2-\frac{\epsilon^2}{2}
 +\frac{N_\epsilon}{1-\epsilon^4}\epsilon^4P_2(R)>0,
 \label{eq:s-three-scaled-polynomial}
\end{equation}
with $1<\frac{N_\epsilon}{1-\epsilon^4}<2$ for $0<\epsilon\le\frac1{100}$.

First consider the fixed annulus where $P_2(R)\le0$.
On this region, $R<2$ and $P_2(R)\ge-1$.
Since $|x|\le\sqrt R$, we have $q_\epsilon=1+2\sqrt\epsilon\,x+\epsilon R\ge(1-\sqrt{\epsilon R})^2$, and hence
\begin{equation}
 \sqrt{q_\epsilon}\ge1-\sqrt{\epsilon R}>
 1-\sqrt{2\epsilon}>\frac45,
 \qquad q_\epsilon-\epsilon>\frac12.
 \label{eq:s-three-q-lower-bound}
\end{equation}
Thus the left-hand side of Eq.~\eqref{eq:s-three-scaled-polynomial} is greater than $1/4-\epsilon^2/2-2\epsilon^4>0$.

Outside this annulus, $P_2(R)>0$, so positivity is immediate unless the other term is negative, that is, $(q_\epsilon-\epsilon)^2-\epsilon^2/2<0$.
In this remaining case,
\begin{equation}
 q_\epsilon<\left(1+\frac1{\sqrt2}\right)\epsilon,
 \qquad
 \sqrt{\epsilon R}\ge1-\sqrt{q_\epsilon}
 >1-\frac43\sqrt\epsilon\ge\frac{13}{15}.
 \label{eq:s-three-s-lower-bound}
\end{equation}
Writing $S=\epsilon R$, we have $S>(13/15)^2>3/4$.
Since $2S^2-4\epsilon S+\epsilon^2$ increases for $S>\epsilon$, it follows that
\begin{equation}
 \epsilon^2P_2(R)=2S^2-4\epsilon S+\epsilon^2
 >2\left(\frac34\right)^2
 -\frac4{100}\frac34>1.
 \label{eq:s-three-scaled-fock-lower-bound}
\end{equation}
The positive term in Eq.~\eqref{eq:s-three-scaled-polynomial} therefore exceeds $\epsilon^2$, while the remaining terms are bounded below by $-\epsilon^2/2$.
This completes the proof of Eq.~\eqref{eq:s-three-explicit-range}.

\subsection{Asymptotic Wigner entropy}
\label{app:s-three-entropy}

Set
\begin{equation}
 \delta_\epsilon=\frac{W_{\sigma_\epsilon}}{W_0}-1,
 \qquad
 \overline n_\epsilon=\Tr(\sigma_\epsilon\hat n).
 \label{eq:s-three-relative-deviation}
\end{equation}
Equation~\eqref{eq:s-entropy-identity} separates the entropy calculation into two terms:
\begin{equation}
 h(W_{\sigma_\epsilon})-h(W_0)
 =2\overline n_\epsilon-D(W_{\sigma_\epsilon}\Vert W_0).
 \label{eq:s-three-entropy-identity}
\end{equation}
The mean photon number follows directly from Eq.~\eqref{eq:s-three-mixture}:
\begin{align}
 2\overline n_\epsilon
